(()=>{const button=document.querySelector('.theme-toggle');const root=document.documentElement;let theme='dark';try{theme=localStorage.getItem('jjta-theme')||'dark'}catch{}function apply(value){theme=value;root.dataset.theme=value;const isLight=value==='light';button.setAttribute('aria-pressed',String(isLight));button.setAttribute('aria-label',isLight?'Aktifkan dark mode':'Aktifkan light mode');button.querySelector('.theme-icon').textContent=isLight?'☾':'☀';button.querySelector('.theme-label').textContent=isLight?'Dark mode':'Light mode';try{localStorage.setItem('jjta-theme',value)}catch{}}button.addEventListener('click',()=>apply(theme==='dark'?'light':'dark'));apply(theme)})();
